import 'package:flutter/material.dart';import 'backend.dart';
class ComposeScreen extends StatefulWidget{const ComposeScreen({super.key});@override State<ComposeScreen> createState()=>_ComposeScreenState();}
class _ComposeScreenState extends State<ComposeScreen>{final controller=TextEditingController();bool sending=false;Future<void> send()async{if(sending||controller.text.trim().isEmpty)return;setState(()=>sending=true);try{await Backend.createPost(controller.text);if(mounted)Navigator.pop(context,true);}catch(e){if(mounted){setState(()=>sending=false);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('投稿できませんでした: '+e.toString())));}}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('投稿')),body:Padding(padding:const EdgeInsets.all(18),child:Column(children:[const AspectRatio(aspectRatio:4/3,child:Card(child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.add_photo_alternate_outlined,size:42),Text('写真は次の接続で有効化')])))),const SizedBox(height:16),TextField(controller:controller,maxLines:4,decoration:const InputDecoration(hintText:'今なにしてる？',border:InputBorder.none)),const Spacer(),SizedBox(width:double.infinity,child:FilledButton(onPressed:sending?null:send,child:Text(sending?'投稿中…':'投稿')))])));}
